    DECIO-MAT-9ANO.xlsx              DECIO DOSSI C E DR EF M PROFIS           9º ano MT   187 alunos x 21 H =  3927
*/

BEGIN;

-- Descritor desta edição que ainda não existe em componentes_habilidades (prova-parana).
ON CONFLICT (tipo_prova, ano_escolar, componente, posicao) DO NOTHING;

-- Planilhas desta parte (k = chave usada em _carga_aluno).
CREATE TEMP TABLE _carga_arquivo (k int PRIMARY KEY, unidade text, ano_escolar text, componente text) ON COMMIT DROP;

-- Descritores da edição: H n de cada (série, componente) -> posição/descrição (HABILIDADE-*.xlsx).
CREATE TEMP TABLE _carga_habilidade (ano_escolar text, componente text, n int, posicao text, descricao text,
  PRIMARY KEY (ano_escolar, componente, n)) ON COMMIT DROP;

-- Alunos: hs = resultados de H 01..H nn separados por espaço ('acertos/total' ou '-').
CREATE TEMP TABLE _carga_aluno (k int, turma text, nome_aluno text, nivel text, hs text) ON COMMIT DROP;

-- Reexecução segura: remove a carga 2026/2 anterior das mesmas planilhas.
DELETE FROM prova_resultados pr
USING _carga_arquivo a
WHERE pr.ano_prova = '2026' AND pr.semestre = '2'
  AND pr.unidade = a.unidade AND pr.ano_escolar = a.ano_escolar AND pr.componente = a.componente;

   avaliado, habilidade_id, habilidade_codigo, descricao_habilidade, acertos, total, percentual,
   componente_habilidade_id)
SELECT '2026', '2', a.unidade, a.ano_escolar, a.componente, al.turma, al.nome_aluno, al.nivel,
       r.total > 0, 'H ' || lpad(h.n::text, 2, '0'), hb.posicao, hb.descricao, r.acertos, r.total,
       CASE WHEN r.total > 0 THEN LEAST(100, GREATEST(0, r.acertos::float8 / r.total * 100)) ELSE 0 END,
       ch.id
FROM _carga_aluno al
JOIN _carga_arquivo a ON a.k = al.k
CROSS JOIN LATERAL unnest(string_to_array(al.hs, ' ')) WITH ORDINALITY AS h(v, n)
JOIN _carga_habilidade hb
  ON hb.ano_escolar = a.ano_escolar AND hb.componente = a.componente AND hb.n = h.n
CROSS JOIN LATERAL (
  SELECT CASE WHEN h.v = '-' THEN 0 ELSE split_part(h.v, '/', 1)::int END AS acertos,
         CASE WHEN h.v = '-' THEN 0 ELSE split_part(h.v, '/', 2)::int END AS total
) r
LEFT JOIN componentes_habilidades ch
  ON ch.tipo_prova = 'prova-parana' AND ch.ano_escolar = a.ano_escolar
  AND ch.componente = a.componente AND ch.posicao = hb.posicao;

COMMIT;

